test_setup_files.dates_test.go:
package main

import (
	"testing"
	"time"
)

func iso(d time.Time) string {
	return d.Format("2006-01-02")
}

func TestZeroReturnsStartUnchanged(t *testing.T) {
	d := time.Date(2024, 6, 1, 0, 0, 0, 0, time.UTC) // Saturday
	if iso(AddBusinessDays(d, 0)) != iso(d) {
		t.Fatalf("expected unchanged")
	}
}

func TestFridayPlusOneSkipsWeekend(t *testing.T) {
	friday := time.Date(2024, 5, 31, 0, 0, 0, 0, time.UTC)
	if got := iso(AddBusinessDays(friday, 1)); got != "2024-06-03" {
		t.Fatalf("got %s", got)
	}
}

func TestMondayPlusFiveLandsNextMonday(t *testing.T) {
	monday := time.Date(2024, 5, 27, 0, 0, 0, 0, time.UTC)
	if got := iso(AddBusinessDays(monday, 5)); got != "2024-06-03" {
		t.Fatalf("got %s", got)
	}
}

func TestCrossesMonthAndYearBoundary(t *testing.T) {
	friday := time.Date(2024, 12, 27, 0, 0, 0, 0, time.UTC)
	if got := iso(AddBusinessDays(friday, 3)); got != "2025-01-01" {
		t.Fatalf("got %s", got)
	}
}

func TestStartingOnAWeekendStillCountsCorrectly(t *testing.T) {
	saturday := time.Date(2024, 6, 1, 0, 0, 0, 0, time.UTC)
	if got := iso(AddBusinessDays(saturday, 1)); got != "2024-06-03" {
		t.Fatalf("got %s", got)
	}
}

