package main

import "time"

func AddBusinessDays(start time.Time, n int) time.Time {
	if n == 0 {
		return start
	}
	current := start
	counted := 0
	for counted < n {
		current = current.AddDate(0, 0, 1)
		if current.Weekday() != time.Saturday && current.Weekday() != time.Sunday {
			counted++
		}
	}
	return current
}

