package main

import "time"

func AddBusinessDays(start time.Time, n int) time.Time {
	if n == 0 {
		return start
	}
	weeks := n / 5
	remainder := n % 5
	calendarDays := weeks*7 + remainder
	return start.AddDate(0, 0, calendarDays)
}
